using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IAsyncLifetime
{
    private readonly HttpListener listener = new();
    private readonly string baseUrl;
    private HttpStatusCode replyStatus = HttpStatusCode.OK;
    private string replyBody = """{"status":"approved"}""";
    private Task serving = Task.CompletedTask;

    private string? receivedMethod;
    private string? receivedPath;
    private string? receivedContentType;
    private string? receivedBody;

    public HttpPaymentGatewayTests()
    {
        var port = new Random().Next(20000, 60000);
        baseUrl = $"http://127.0.0.1:{port}";
        listener.Prefixes.Add(baseUrl + "/");
    }

    public Task InitializeAsync()
    {
        listener.Start();
        serving = Task.Run(async () =>
        {
            try
            {
                while (true)
                {
                    var ctx = await listener.GetContextAsync();
                    receivedMethod = ctx.Request.HttpMethod;
                    receivedPath = ctx.Request.Url!.AbsolutePath;
                    receivedContentType = ctx.Request.ContentType;
                    using (var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8))
                        receivedBody = await reader.ReadToEndAsync();
                    var bytes = Encoding.UTF8.GetBytes(replyBody);
                    ctx.Response.StatusCode = (int)replyStatus;
                    ctx.Response.ContentType = "application/json";
                    await ctx.Response.OutputStream.WriteAsync(bytes);
                    ctx.Response.Close();
                }
            }
            catch (Exception) when (!listener.IsListening) { }
        });
        return Task.CompletedTask;
    }

    public async Task DisposeAsync()
    {
        listener.Close();
        await serving;
    }

    private HttpPaymentGateway Gateway() => new(new HttpClient { BaseAddress = new Uri(baseUrl) });

    [Fact]
    public async Task The_authorization_is_posted_as_json_with_reference_amount_and_currency()
    {
        await Gateway().AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

        Assert.Equal("POST", receivedMethod);
        Assert.Equal("/v1/authorizations", receivedPath);
        Assert.StartsWith("application/json", receivedContentType);
        using var json = JsonDocument.Parse(receivedBody!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        replyBody = """{"status":"approved"}""";

        var outcome = await Gateway().AuthorizeAsync("ORD-1", new Money(5, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        replyBody = """{"status":"declined"}""";

        var outcome = await Gateway().AuthorizeAsync("ORD-2", new Money(5, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        replyBody = """{"status":"approved","id":"auth_1","risk":{"score":3}}""";

        var outcome = await Gateway().AuthorizeAsync("ORD-3", new Money(5, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_an_explicit_approval_is_never_treated_as_approved(string body)
    {
        replyBody = body;

        var outcome = await Gateway().AuthorizeAsync("ORD-4", new Money(5, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_even_when_the_body_says_approved()
    {
        replyStatus = HttpStatusCode.PaymentRequired;
        replyBody = """{"status":"approved"}""";

        var outcome = await Gateway().AuthorizeAsync("ORD-5", new Money(5, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(HttpStatusCode.BadRequest)]
    [InlineData(HttpStatusCode.Unauthorized)]
    [InlineData(HttpStatusCode.InternalServerError)]
    [InlineData(HttpStatusCode.ServiceUnavailable)]
    public async Task A_provider_error_is_raised_and_not_mistaken_for_a_decision(HttpStatusCode status)
    {
        replyStatus = status;
        replyBody = """{"error":"nope"}""";

        await Assert.ThrowsAsync<HttpRequestException>(() =>
            Gateway().AuthorizeAsync("ORD-6", new Money(5, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task A_body_that_is_not_json_is_raised()
    {
        replyBody = "<html>oops</html>";

        await Assert.ThrowsAnyAsync<JsonException>(() =>
            Gateway().AuthorizeAsync("ORD-8", new Money(5, "EUR"), CancellationToken.None));
    }
}
